                    appStorePrivacyPolicy = "http://www.mynetdiary.com/privacy.html",
                    googlePlayPrivacyPolicy = "https://www.kalee.app/en/privacy",
                    appWebsiteUrl = "https://www.mynetdiary.com/iPhone.html",
                ),
